select 'vat-ly', '10', v.tid, v.tname, 'bai_tap', v.q->>'type', v.q->>'difficulty', 'ai', v.q, public.question_content_hash(v.q), true, 'nap-vl10-c6-20261020'
from (values ($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật chuyển động tròn đều với chu kì $\\text{T,}$ tần số góc $\\text{ω,}$ số vòng mà vật đi được trong một giây là $\\text{f.}$ Hệ thức <strong>đúng</strong> là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với chuyển động tròn đều, tần số góc là $\\omega = \\frac{2\\pi}{T}$, trong đó $T$ là chu kì (thời gian vật đi hết một vòng).</p><p class=\"text-base leading-relaxed my-2\">Tần số $f$ là số vòng vật đi được trong một giây, nên $f = \\frac{1}{T}$, suy ra $T = \\frac{1}{f}$ và $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $\\omega = \\frac{2\\pi}{T}$: đúng.</p><p class=\"text-base leading-relaxed my-2\">B. $\\omega = \\frac{2\\pi}{f}$: sai, vì $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">C. $T = \\omega f$: sai, vì $T = \\frac{1}{f}$.</p><p class=\"text-base leading-relaxed my-2\">D. $T = \\frac{1}{f^2}$: sai, vì $T = \\frac{1}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là A.</p>","options":["$\\text{ω}=\\frac{\\text{2π}}{\\text{T}}\\text{.}$","$\\text{ω}=\\frac{\\text{2π}}{\\text{f}}\\text{.}$","$\\text{T}=\\text{ωf.}$","$\\text{T}=\\frac{\\text{1}}{\\text{f}^{\\text{2}}}\\text{.}$"],"answer":0}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công thức nào sau đây là <strong>đúng</strong>?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với dao động điều hòa, tần số góc $\\omega$, tần số $f$ và chu kì $T$ liên hệ theo các công thức:</p><p class=\"text-base leading-relaxed my-2\">$\\omega = 2\\pi f = \\dfrac{2\\pi}{T}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{\\omega}{f} = 2\\pi$ và $\\omega T = 2\\pi$.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $\\dfrac{T}{f}$ không bằng $2\\pi$ (vì $T \\cdot f = 1$). Sai.</p><p class=\"text-base leading-relaxed my-2\">B. $\\dfrac{T}{\\omega}$ không bằng $2\\pi$ (đúng là $T\\omega = 2\\pi$). Sai.</p><p class=\"text-base leading-relaxed my-2\">C. $\\dfrac{\\omega}{f} = 2\\pi$ đúng theo $\\omega = 2\\pi f$. Đúng.</p><p class=\"text-base leading-relaxed my-2\">D. $\\dfrac{f}{T}$ không bằng 1 (vì $f = \\dfrac{1}{T}$ nên $\\dfrac{f}{T} = \\dfrac{1}{T^2}$). Sai.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là C.</p>","options":["$\\frac{\\text{T}}{\\text{f}}\\text{ = 2π.}$","$\\frac{\\text{T}}{\\text{ω}}\\text{ = 2π.}$","$\\frac{\\text{ω}}{\\text{f}}\\text{ = 2π.}$","$\\frac{\\text{f}}{\\text{T}}\\text{ = 1.}$"],"answer":2}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công thức liên hệ giữa vận tốc dài, chu kì T và tần số f là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động tròn đều, vận tốc dài có độ lớn bằng quãng đường đi được chia cho thời gian đi hết quãng đường đó.</p><p class=\"text-base leading-relaxed my-2\">Trong một chu kì $T$, vật đi được một vòng tròn có chu vi $s = 2\\pi r$, với $r$ là bán kính quỹ đạo.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc dài: $v = \\dfrac{s}{T} = \\dfrac{2\\pi r}{T}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tần số $f = \\dfrac{1}{T}$, nên $T = \\dfrac{1}{f}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Thay vào: $v = \\dfrac{2\\pi r}{T} = 2\\pi r f$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $v = \\dfrac{2\\pi r}{T} = 2\\pi r f$, đáp án đúng là <b>C</b>.</p><p class=\"text-base leading-relaxed my-2\">Loại các phương án còn lại: A và B sai vì có $T$ hoặc $f$ nằm ở vị trí không đúng (ví dụ $2\\pi T/r$); D sai vì $v = 2\\pi r T$ không đúng thứ nguyên.</p>","options":["$\\text{v = }\\frac{\\text{2πT}}{\\text{r}}\\text{ = }\\frac{\\text{2π}}{\\text{rf}}\\text{.}$","$\\text{v = }\\frac{\\text{2π}}{\\text{Tr}}\\text{ = }\\frac{\\text{2πf}}{\\text{r}}\\text{.}$","$\\text{v = }\\frac{\\text{2πr}}{\\text{T}}\\text{ = 2πrf.}$","$\\text{v = 2πrT = }\\frac{\\text{2πr}}{\\text{f}}\\text{.}$"],"answer":2}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Công thức liên hệ giữa vận tốc góc, chu kì và tần số là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Với chuyển động tròn đều, vận tốc góc $\\omega$ liên hệ với chu kì $T$ và tần số $f$ theo công thức chữ: góc quét được trong một chu kì là $2\\pi$ rad, nên $\\omega = \\dfrac{2\\pi}{T}$.</p><p class=\"text-base leading-relaxed my-2\">Vì tần số $f = \\dfrac{1}{T}$ nên $T = \\dfrac{1}{f}$, suy ra $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">Vậy công thức đúng là $\\omega = \\dfrac{2\\pi}{T}$ và $\\omega = 2\\pi f$, tương ứng phương án A.</p>","options":["$\\text{ω = }\\frac{\\text{2π}}{\\text{T}}\\text{,} \\text{ω = 2πf.}$","$\\text{ω = 2πT,} \\text{ω = 2πf.}$","$\\text{ω = 2πT,} \\text{ω = }\\frac{\\text{2π}}{\\text{f}}\\text{.}$","$\\text{ω = }\\frac{\\text{2π}}{\\text{T}}\\text{,} \\text{ω = }\\frac{\\text{2π}}{\\text{f}}\\text{.}$"],"answer":0}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn câu <strong>sai</strong>. Trong chuyển động tròn đều bán kính r, chu kì T, tần số $\\text{f}$ thì</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động tròn đều, chu kì $T$ là thời gian để chất điểm đi được <b>một vòng</b>, còn tần số $f$ là số vòng đi được trong <b>một giây</b>. Ta có $f = \\dfrac{1}{T}$.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\"><b>A. Đúng.</b> Theo định nghĩa, chu kì là thời gian để vật đi hết một vòng.</p><p class=\"text-base leading-relaxed my-2\"><b>B. Đúng.</b> Mỗi vòng có độ dài $2\\pi r$, trong một giây đi được $f$ vòng nên quãng đường đi được là $s = 2\\pi r f$.</p><p class=\"text-base leading-relaxed my-2\"><b>C. Sai.</b> Trong $T$ giây chất điểm chỉ đi được đúng <b>1 vòng</b>, không phải $f$ vòng. (Trong $T$ giây số vòng là $\\dfrac{T}{T}=1$.)</p><p class=\"text-base leading-relaxed my-2\"><b>D. Đúng.</b> Từ $f = \\dfrac{1}{T}$, khi $T' = 2T$ thì $f' = \\dfrac{1}{2T} = \\dfrac{f}{2}$, tức tần số giảm đi hai lần.</p><p class=\"text-base leading-relaxed my-2\">Vậy phương án sai là <b>C</b>.</p>","options":["chất điểm đi được một vòng trên đường tròn hết T giây.","cứ mỗi giây, chất điểm đi được $\\text{f}$ vòng, tức là đi được một quãng đường bằng $\\text{2πfr}$.","chất điểm đi được $\\text{f}$ vòng trong T giây.","nếu chu kì T tăng lên hai lần thì tần số $\\text{f}$ giảm đi hai lần."],"answer":2}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong các chuyển động tròn đều</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các công thức của chuyển động tròn đều: $\\omega=\\dfrac{2\\pi}{T}=2\\pi f$; $v=\\omega r=2\\pi f r$; $T=\\dfrac{1}{f}$.</p><p class=\"text-base leading-relaxed my-2\">A: $\\omega=\\dfrac{2\\pi}{T}$ nên T lớn thì $\\omega$ nhỏ</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ đúng.</p><p class=\"text-base leading-relaxed my-2\">B: cùng r, $v=2\\pi f r$ nên f nhỏ thì v nhỏ</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ đúng.</p><p class=\"text-base leading-relaxed my-2\">C: cùng T thì $\\omega=\\dfrac{2\\pi}{T}$ như nhau, không phụ thuộc bán kính</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ sai.</p><p class=\"text-base leading-relaxed my-2\">D: $T=\\dfrac{1}{f}$ nên f nhỏ thì T lớn</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ đúng, và đúng trong mọi trường hợp, không cần điều kiện thêm.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>D</b>.</p>","options":["chuyển động nào có chu kỳ quay lớn hơn thì có tốc độ góc nhỏ hơn.","có cùng bán kính, chuyển động nào có tần số quay nhỏ hơn thì có tốc độ nhỏ hơn.","có cùng chu kỳ, chuyển động nào có bán kính lớn hơn thì có tốc độ góc lớn hơn.","chuyển động nào có tần số nhỏ hơn thì có chu kỳ lớn hơn."],"answer":3}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật chuyển động tròn đều với bán kính $\\text{r,}$ tốc độ góc $\\text{ω.}$ Tốc độ của vật</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động tròn đều, tốc độ dài liên hệ với tốc độ góc và bán kính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$v = \\omega r$</p><p class=\"text-base leading-relaxed my-2\">Với $\\omega$ không đổi, $v$ tỉ lệ thuận với $r$ (đồng biến theo $r$).</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai, tốc độ phụ thuộc vào $r$ vì $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">B. Sai, tốc độ thay đổi khi $\\omega$ thay đổi vì $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">C. Sai, tốc độ bằng tích (không phải thương) của $\\omega$ và $r$.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng, tốc độ tỉ lệ với bán kính $r$.</p>","options":["không phụ thuộc vào $\\text{r.}$","luôn không đổi khi thay đổi tốc độ góc $\\text{ω.}$","bằng thương số của bán kính $\\text{r}$ và tốc độ góc $\\text{ω.}$","tỉ lệ với bán kính $\\text{r.}$"],"answer":3}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chọn phát biểu <strong>sai</strong>. Vật chuyển động tròn đều với chu kì $\\text{T}$ không đổi, khi bán kính $\\text{r}$ của quĩ đạo</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chuyển động tròn đều có chu kì $T$ không đổi, nên tốc độ góc $\\omega = \\dfrac{2\\pi}{T}$ cũng không đổi. Tốc độ góc chỉ phụ thuộc vào chu kì, không phụ thuộc bán kính quỹ đạo.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Tốc độ dài $v = \\omega r$ với $\\omega$ không đổi, nên $r$ giảm thì $v$ giảm. Phát biểu <b>đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">B. Vì $\\omega = \\dfrac{2\\pi}{T}$ và $T$ không đổi, nên khi $r$ thay đổi thì $\\omega$ vẫn không đổi. Phát biểu <b>đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">C. Gia tốc hướng tâm $a_{ht} = \\omega^2 r$ với $\\omega$ không đổi, nên $r$ tăng thì $a_{ht}$ tăng. Phát biểu <b>đúng</b>.</p><p class=\"text-base leading-relaxed my-2\">D. Khi $r$ tăng, $\\omega$ vẫn không đổi (vì $T$ không đổi), không tăng. Phát biểu <b>sai</b>.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu sai là D.</p>","options":["giảm thì tốc độ giảm.","thay đổi thì tốc độ góc không đổi.","tăng thì độ lớn gia tốc hướng tâm tăng.","tăng thì tốc độ góc tăng."],"answer":3}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Phát biểu nào sau đây là <strong>đúng</strong> khi nói về chuyển động tròn đều</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động tròn đều: $v=\\omega r$, $\\omega=\\dfrac{2\\pi}{T}$, $a_{ht}=\\dfrac{v^2}{r}=\\omega^2 r=v\\omega$.</p><p class=\\\"text-base leading-relaxed my-2\\\">A: $v=\\omega r$ nên tốc độ dài phụ thuộc bán kính quỹ đạo (khi $\\omega$ cho trước) &rArr; Đúng.</p><p class=\"text-base leading-relaxed my-2\">B: Với $v$ và $\\omega$ cho trước thì $a_{ht}=v\\omega$ là hằng số, không phụ thuộc $r$ &rArr; Sai.</p><p class=\"text-base leading-relaxed my-2\">C: Tốc độ góc $\\omega=\\dfrac{2\\pi}{T}$ chỉ phụ thuộc chu kì, không phụ thuộc $r$ &rArr; Sai.</p><p class=\"text-base leading-relaxed my-2\">D: Sai vì $v$ phụ thuộc $r$.</p><p class=\"text-base leading-relaxed my-2\">Chọn <b>A</b>.</p>","options":["Tốc độ dài của chuyển động tròn đều phụ thuộc vào bán kính quỹ đạo.","Với v và $\\text{ω}$ cho trước, gia tốc hướng tâm phụ thuộc vào bán kính quỹ đạo.","Tốc độ góc của chuyển động tròn đều phụ thuộc vào bán kính quỹ đạo.","Cả ba đại lượng trên đều không phụ thuộc vào bán kính quỹ đạo."],"answer":0}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính gia tốc hướng tâm","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Gia tốc hướng tâm trong chuyển động tròn đều</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong chuyển động tròn đều, gia tốc hướng tâm có độ lớn được xác định bởi công thức chữ: gia tốc hướng tâm bằng bình phương tốc độ dài chia cho bán kính quỹ đạo.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $a_{ht} = \\dfrac{v^2}{R}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $v$ là tốc độ dài (không đổi về độ lớn) và $R$ là bán kính quỹ đạo tròn.</p><p class=\"text-base leading-relaxed my-2\">Khi bán kính $R$ không đổi, ta có $a_{ht} = \\dfrac{1}{R}\\cdot v^2$, tức $a_{ht}$ tỉ lệ thuận với $v^2$ (với hệ số tỉ lệ $\\dfrac{1}{R}$ là hằng số).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc hướng tâm tỉ lệ thuận với bình phương tốc độ $v^2$ khi $R$ là hằng số. Đáp án đúng là <b>B</b>.</p>","options":["tỉ lệ thuận với tốc độ $\\text{v}$ với R là hằng số.","tỉ lệ thuận với bình phương tốc độ $\\text{v}^{\\text{2}}$ với R là hằng số.","tỉ lệ nghịch với bình phương tốc độ $\\text{v}^{\\text{2}}$ với R là hằng số.","tỉ lệ nghịch với tốc độ $\\text{v}$ với R là hằng số."],"answer":1}$q$::jsonb, 148, $q$Tính gia tốc hướng tâm$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trên một cánh quạt đang quay đều, người ta lấy hai điểm có bán kính $\\text{R}_{\\text{1}}$ và $\\text{R}_{\\text{2}}$ với $\\text{R}_{\\text{1}}=\\text{2}\\text{R}_{\\text{2}}$ thì tốc độ của 2 điểm đó lần lượt là $\\text{v}_{\\text{1}}$ và $\\text{v}_{\\text{2}}\\text{.}$ Biểu thức <strong>đúng</strong> là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Các điểm trên cùng một cánh quạt quay đều có cùng tốc độ góc $\\omega$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ dài của một điểm chuyển động tròn đều: $v = \\omega R$.</p><p class=\"text-base leading-relaxed my-2\">Với hai điểm: $v_1 = \\omega R_1$ và $v_2 = \\omega R_2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\dfrac{v_1}{v_2} = \\dfrac{R_1}{R_2} = 2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v_1 = 2v_2$</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là A.</p>","options":["$\\text{v}_{\\text{1}}=\\text{2}\\text{v}_{\\text{2}}\\text{.}$","$\\text{v}_{\\text{2}}=\\text{2}\\text{v}_{\\text{1}}\\text{.}$","$\\text{v}_{\\text{1}}=\\text{v}_{\\text{2}}\\text{.}$","$\\text{v}_{\\text{2}}=\\sqrt{\\text{2}}\\text{v}_{\\text{1}}\\text{.}$"],"answer":0}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trên một cánh quạt đang quay đều, người ta lấy hai điểm có bán kính $\\text{R}_{\\text{1}}$ và $\\text{R}_{\\text{2}}$ với $\\text{R}_{\\text{1}}=\\text{4}\\text{R}_{\\text{2}}$ thì chu kì quay của 2 điểm đó lần lượt là $\\text{T}_{\\text{1}}$ và $\\text{T}_{\\text{2}}\\text{.}$ Biểu thức <strong>đúng</strong> là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Cánh quạt là một vật rắn quay đều quanh một trục cố định. Mọi điểm trên cùng vật rắn quay quanh một trục đều có cùng chu kì quay, không phụ thuộc vào bán kính.</p><p class=\"text-base leading-relaxed my-2\">Vì hai điểm đều nằm trên cùng cánh quạt đang quay đều nên:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T_1 = T_2$</p><p class=\"text-base leading-relaxed my-2\">Dữ kiện $R_1 = 4R_2$ chỉ liên quan đến tốc độ dài $v = \\omega R$, không ảnh hưởng đến chu kì.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là C.</p>","options":["$\\text{T}_{\\text{1}}=\\text{2}\\text{T}_{\\text{2}}\\text{.}$","$\\text{T}_{\\text{2}}=\\text{2}\\text{T}_{\\text{1}}\\text{.}$","$\\text{T}_{\\text{1}}=\\text{T}_{\\text{2}}\\text{.}$","$\\text{T}_{\\text{1}}=\\text{4}\\text{T}_{\\text{2}}\\text{.}$"],"answer":2}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Chu kỳ của kim phút là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chu kỳ $T$ là khoảng thời gian để vật (ở đây là đầu mút kim phút) quay được một vòng.</p><p class=\"text-base leading-relaxed my-2\">Kim phút quay đúng một vòng trên mặt đồng hồ trong 60 phút.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T = 60 \\text{ phút} = 3600 \\text{ s}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: chu kỳ của kim phút là 60 phút, đáp án C.</p>","options":["$\\text{1 phut.}$","$\\text{360 s.}$","$\\text{60 phut.}$","$\\text{10 phut.}$"],"answer":2}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trục máy quay có tốc độ quay là $\\text{n} \\text{vòng/phút.}$ Tốc độ góc ω tính theo rad/s là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị tốc độ quay: 1 vòng = $2\\pi$ rad, 1 phút = 60 s, nên $n$ vòng/phút $= \\dfrac{2\\pi n}{60}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = \\dfrac{2\\pi n}{60} = \\dfrac{\\pi n}{30}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là B.</p>","options":["$\\text{2πn.}$","$\\frac{\\text{πn}}{\\text{30}}\\text{.}$","$\\text{4}\\text{π}^{\\text{2}}\\text{n}^{\\text{2}}\\text{.}$","$\\text{4π}\\text{n}^{\\text{2}}\\text{.}$"],"answer":1}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Trong máy Cyclotron các proton khi được tăng tốc đến tốc độ v thì chuyển động tròn đều với bán kính R. Chu kì quay của proton là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Proton chuyển động tròn đều với bán kính $R$ và tốc độ $v$. Quãng đường đi được trong một vòng là chu vi đường tròn: $s = 2\\pi R$.</p><p class=\"text-base leading-relaxed my-2\">Chu kì $T$ là thời gian để đi hết một vòng với tốc độ không đổi $v$: $T = \\dfrac{s}{v}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T = \\dfrac{2\\pi R}{v}$.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là <b>A</b>.</p>","options":["$\\text{T}=\\frac{\\text{2πR}}{\\text{v}}\\text{.}$","$\\text{T}=\\text{Rv.}$","$\\text{T}=\\frac{\\text{2πv}}{\\text{R}}\\text{.}$","$\\text{T}=\\text{R}^{\\text{2}}\\text{v.}$"],"answer":0}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vành ngoài của một bánh xe ô tô có bán kính là $\\text{25 cm.}$ Tốc độ góc của một điểm trên vành ngoài của bánh xe khi ô tô đang chạy với tốc độ dài 36 km/h là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Điểm trên vành ngoài bánh xe chuyển động tròn đều với bán kính $r$ và tốc độ dài $v$ (cũng là tốc độ của ô tô). Mối liên hệ giữa tốc độ dài và tốc độ góc là $v = \\omega r$, suy ra $\\omega = \\dfrac{v}{r}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $v = 36 \\text{ km/h} = \\dfrac{36}{3,6} = 10 \\text{ m/s}$; $r = 25 \\text{ cm} = 0,25 \\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = \\dfrac{10}{0,25} = 40 \\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy tốc độ góc của điểm trên vành ngoài bánh xe là $40 \\text{ rad/s}$. Đáp án <b>A</b>.</p>","options":["40 rad/s.","50 rad/s.","60 rad/s.","70 rad/s."],"answer":0}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một bánh xe quay đều $\\text{100}$ vòng trong thời gian 2 s. Chu kì quay của bánh xe là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chu kì quay là thời gian để vật quay được một vòng, được tính bằng công thức $T = \\dfrac{t}{N}$, trong đó $t$ là thời gian quay và $N$ là số vòng quay được.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $t = 2\\ \\text{s}$ và $N = 100$ vòng:</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{2}{100} = 0{,}02\\ \\text{s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy chu kì quay của bánh xe là $0{,}02\\ \\text{s}$, chọn đáp án A.</p>","options":["0,02 s.","0,01 s.","0,04 s.","0,05 s."],"answer":0}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một bánh xe quay đều $\\text{100}$ vòng trong $\\text{4}$ giây. Chu kì quay của bánh xe là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chu kì $T$ là thời gian bánh xe quay được một vòng, được tính bằng công thức $T = \\dfrac{t}{N}$, trong đó $t$ là tổng thời gian và $N$ là số vòng quay.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $t = 4\\ \\text{s}$ và $N = 100$ vòng:</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{4}{100} = 0{,}04\\ \\text{s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy chu kì quay của bánh xe là $0{,}04\\ \\text{s}$, đáp án A.</p>","options":["$\\text{0,04 s.}$","$\\text{0,02 s.}$","$\\text{25 s.}$","$\\text{50 s.}$"],"answer":0}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một chất điểm chuyển động đều trên một quỹ đạo tròn. Biết trong một phút nó đi được $\\text{300}$ vòng. Tốc độ góc của chất điểm bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị thời gian: $\\Delta t = 1\\ \\text{phút} = 60\\ \\text{s}$.</p><p class=\"text-base leading-relaxed my-2\">Mỗi vòng chất điểm quay được góc $2\\pi$ rad, nên trong 300 vòng góc quay là $\\Delta\\alpha = 300 \\cdot 2\\pi = 600\\pi\\ \\text{rad}$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc của chuyển động tròn đều: $\\omega = \\dfrac{\\Delta\\alpha}{\\Delta t}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\omega = \\dfrac{600\\pi}{60} = 10\\pi\\ \\text{rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ góc bằng $10\\pi\\ \\text{rad/s}$, đáp án C.</p>","options":["$\\text{50π rad/s.}$","$\\text{50 rad/s.}$","$\\text{10π rad/s.}$","$\\text{10 rad/s.}$ \n<strong>Hướng dẫn giải.</strong> \nTa có $\\text{ω}=\\frac{\\text{Δα}}{\\text{Δt}}=\\frac{\\text{300.2π}}{\\text{60}}=\\text{10π rad/s.}$"],"answer":2}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một bánh xe bán kính quay đều $\\text{100}$ vòng trong thời gian 2 s. Tần số quay của bánh xe là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số quay của vật chuyển động tròn đều là số vòng quay được trong một giây: $f = \\dfrac{N}{t}$, với $N$ là số vòng quay và $t$ là thời gian (s).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $N = 100$ vòng, $t = 2$ s, ta có $f = \\dfrac{100}{2} = 50$ (vòng/s).</p><p class=\"text-base leading-relaxed my-2\">Vì 1 vòng/s = 1 Hz nên $f = 50$ Hz.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số quay của bánh xe là $50$ Hz, chọn đáp án B.</p>","options":["25Hz.","50Hz.","200Hz.","100Hz."],"answer":1}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Mặt Trăng quay một vòng Trái Đất hết $\\text{27}$ ngày – đêm. Tốc độ góc của Mặt Trăng quay quanh Trái Đất là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tốc độ góc của một chuyển động tròn đều được tính theo công thức: $\\omega = \\dfrac{2\\pi}{T}$, trong đó $T$ là chu kì quay.</p><p class=\"text-base leading-relaxed my-2\">Chu kì quay của Mặt Trăng: $T = 27$ ngày $= 27 \\cdot 24 \\cdot 3600$ s $= 2{,}3328.10^{6}$ s.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc: $\\omega = \\dfrac{2\\pi}{2{,}3328.10^{6}} \\approx 2{,}7.10^{-6}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ góc của Mặt Trăng quanh Trái Đất là $2{,}7.10^{-6}$ rad/s, chọn đáp án D.</p>","options":["$\\text{5,4.1}\\text{0}^{\\text{-6}}\\text{ rad/s.}$","$\\text{3,6.1}\\text{0}^{-\\text{6}}\\text{ rad/s.}$","$\\text{4,3.1}\\text{0}^{-\\text{6}}\\text{ rad/s.}$","$\\text{2,7.1}\\text{0}^{-\\text{6}}\\text{ rad/s.}$"],"answer":3}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh nhân tạo của Trái Đất ở độ cao 300 m bay với vận tốc 7 km/s. Coi vệ tinh chuyển động tròn đều và bán kính Trái Đất bằng 6400 km. Tốc độ góc của vệ tinh là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Trái Đất nên bán kính quỹ đạo bằng bán kính Trái Đất cộng độ cao: $r = R + h$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 6400\\text{ km} + 0{,}3\\text{ km} = 6400{,}3\\text{ km} = 6{,}4003\\cdot 10^{6}\\text{ m}$, $v = 7\\text{ km/s} = 7000\\text{ m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Công thức liên hệ vận tốc dài và tốc độ góc trong chuyển động tròn đều: $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = \\dfrac{v}{r} = \\dfrac{7000}{6{,}4003\\cdot 10^{6}} \\approx 1{,}09\\cdot 10^{-3}\\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ góc của vệ tinh là $\\omega \\approx 1{,}09\\cdot 10^{-3}\\text{ rad/s}$, chọn đáp án B.</p>","options":["$\\text{1,47.1}\\text{0}^{-\\text{3}}\\text{ rad/s.}$","$\\text{1,09.1}\\text{0}^{-\\text{3}}\\text{ rad/s.}$","$\\text{1,63.1}\\text{0}^{-\\text{3}}\\text{ rad/s.}$","$\\text{1,92.1}\\text{0}^{-\\text{3}}\\text{ rad/s.}$."],"answer":1}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh nhân tạo của Trái Đất ở độ cao 300 m bay với vận tốc 7,0 km/s. Coi vệ tinh chuyển động tròn đều và bán kính Trái Đất bằng 6400 km. Tần số của về tinh quay xung quanh Trái Đất <strong>gần với giá trị</strong> nào nhất?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Trái Đất, lực hấp dẫn đóng vai trò lực hướng tâm. Bán kính quỹ đạo là khoảng cách từ tâm Trái Đất đến vệ tinh:</p><p class=\"text-base leading-relaxed my-2\">$r = R + h$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = 6400 + 0{,}3 = 6400{,}3 \\text{ km} = 6{,}4003.10^{6} \\text{ m}$</p><p class=\"text-base leading-relaxed my-2\">Chuyển động tròn đều có tốc độ góc:</p><p class=\"text-base leading-relaxed my-2\">$\\omega = \\dfrac{v}{r}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = \\dfrac{7{,}0.10^{3}}{6{,}4003.10^{6}} \\approx 1{,}0937.10^{-3} \\text{ rad/s}$</p><p class=\"text-base leading-relaxed my-2\">Tần số liên hệ với tốc độ góc bởi $\\omega = 2\\pi f$:</p><p class=\"text-base leading-relaxed my-2\">$f = \\dfrac{\\omega}{2\\pi}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow f = \\dfrac{1{,}0937.10^{-3}}{2\\pi} \\approx 1{,}74.10^{-4} \\text{ Hz}$</p><p class=\"text-base leading-relaxed my-2\">So sánh với các phương án, giá trị $1{,}74.10^{-4}$ Hz gần nhất với $2{,}1.10^{-4}$ Hz.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số quay của vệ tinh xấp xỉ $2{,}1.10^{-4}$ Hz, chọn đáp án D.</p>","options":["$\\text{3.1}\\text{0}^{\\text{-4}}\\text{ Hz.}$","$\\text{5.1}\\text{0}^{-\\text{4}}\\text{ Hz.}$","$\\text{4.1}\\text{0}^{-\\text{4}}\\text{ Hz.}$","$\\text{2.1}\\text{0}^{-\\text{4}}\\text{ Hz.}$"],"answer":3}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một chiếc xe chuyển động đều, vận tốc 36 km/h. Khi đó một điểm trên vành xe vạch được một cùng 90$^{0}$ sau 0,05 s. Số vòng bánh xe quay được trong 10 s là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị vận tốc: $v = 36$ km/h $= 36 \\cdot \\dfrac{1000}{3600} = 10$ m/s.</p><p class=\"text-base leading-relaxed my-2\">Góc quay của một điểm trên vành bánh xe trong thời gian $\\Delta t = 0{,}05$ s là $\\Delta\\varphi = 90^\\circ = \\dfrac{\\pi}{2}$ rad.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc của bánh xe (chuyển động tròn đều): $\\omega = \\dfrac{\\Delta\\varphi}{\\Delta t} = \\dfrac{\\pi/2}{0{,}05} = 10\\pi$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Tần số quay của bánh xe: $f = \\dfrac{\\omega}{2\\pi} = \\dfrac{10\\pi}{2\\pi} = 5$ vòng/s.</p><p class=\"text-base leading-relaxed my-2\">Số vòng bánh xe quay được trong $t = 10$ s: $N = f \\cdot t = 5 \\cdot 10 = 50$ vòng.</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra: bán kính $R = \\dfrac{v}{\\omega} = \\dfrac{10}{10\\pi} = \\dfrac{1}{\\pi}$ m $\\approx 0{,}32$ m, hợp lý với bánh xe.</p><p class=\"text-base leading-relaxed my-2\">Vậy bánh xe quay được 50 vòng trong 10 s, chọn đáp án D.</p>","options":["25.","30.","40.","50."],"answer":3}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tính gia tốc hướng tâm","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một chất điểm chuyển động trên một đường tròn bán kính $\\text{R = 15 m,}$ với vận tốc dài $\\text{54 km/h.}$ Gia tốc hướng tâm của chất điểm là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị vận tốc: $v = 54 \\text{ km/h} = \\dfrac{54\\,000 \\text{ m}}{3600 \\text{ s}} = 15 \\text{ m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Gia tốc hướng tâm của chất điểm chuyển động tròn đều: $a_{ht} = \\dfrac{v^2}{R}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $a_{ht} = \\dfrac{15^2}{15} = \\dfrac{225}{15} = 15 \\text{ m/s}^2$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: gia tốc hướng tâm bằng $15 \\text{ m/s}^2$, chọn đáp án B.</p>","options":["$\\text{1 m/}\\text{s}^{\\text{2}}\\text{.}$","$\\text{15 m/}\\text{s}^{\\text{2}}\\text{.}$","$\\text{225 m/}\\text{s}^{\\text{2}}\\text{.}$$$","một giá trị khác."],"answer":1}$q$::jsonb, 148, $q$Tính gia tốc hướng tâm$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Tần số quay của kim giờ trên mặt đồng hồ</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Kim giờ quay một vòng hết $T = 12\\ \\text{h}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $T = 12 \\cdot 3600 = 43200\\ \\text{s}$.</p><p class=\"text-base leading-relaxed my-2\">Tần số quay là số vòng trong một giây, quan hệ với chu kì theo công thức $f = \\dfrac{1}{T}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow f_g = \\dfrac{1}{43200} \\approx 2{,}31\\cdot 10^{-5}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>.</p>","options":["$\\text{f}_{\\text{g}}\\text{=4,62.1}\\text{0}^{\\text{-5}}\\text{ Hz.}$","$\\text{f}_{\\text{g}}\\text{= 2, 31. 1}\\text{0}^{\\text{- 5}}\\text{ Hz.}$","$\\text{f}_{\\text{g}}\\text{=2,78.1}\\text{0}^{\\text{-4}}\\text{ Hz.}$","$\\text{f}_{\\text{g}}\\text{= 1, 16. 1}\\text{0}^{\\text{- 5}}\\text{ Hz.}$"],"answer":1}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một quạt máy quay được $\\text{180} \\text{vòng}$ trong thời gian $\\text{30 s,}$ cánh quạt dài $\\text{0,4 m.}$ Vận tốc dài của một điểm ở đầu cánh quạt là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số quay của cánh quạt: $f = \\dfrac{N}{t}$, trong đó $N$ là số vòng quay và $t$ là thời gian.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow f = \\dfrac{180}{30} = 6 \\text{ vòng/s} = 6 \\text{ Hz}$</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc: $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = 2\\pi \\cdot 6 = 12\\pi \\text{ rad/s}$</p><p class=\"text-base leading-relaxed my-2\">Vận tốc dài của điểm ở đầu cánh quạt (bán kính $r = 0{,}4$ m): $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = 12\\pi \\cdot 0{,}4 = 4{,}8\\pi \\text{ m/s} \\approx 15{,}1 \\text{ m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy đáp án đúng là C.</p>","options":["$\\frac{\\text{π}}{\\text{3}}\\text{ m/s.}$","$\\text{2,4π m/s.}$.","$\\text{4,8π m/s.}$","$\\text{2,4 m/s.}$"],"answer":2}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đồng hồ công cộng gắn trên tháp chuông ở trung tâm thành phố có kim phút dài $\\text{1,2 m}$ và kim giờ dài $\\text{90 cm.}$ Tốc độ dài của hai đầu mút hai kim đó lần lượt là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Kim quay đều, tốc độ dài của một điểm trên kim: $v = \\omega R = \\dfrac{2\\pi}{T}R$, với $R$ là chiều dài kim và $T$ là chu kì quay.</p><p class=\"text-base leading-relaxed my-2\"><b>Kim phút:</b> chu kì $T_p = 60\\text{ min} = 3600\\text{ s}$, bán kính $R_p = 1{,}2\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">$v_p = \\dfrac{2\\pi}{3600}\\cdot 1{,}2 \\approx 2{,}09\\cdot 10^{-3}\\text{ m/s}$</p><p class=\"text-base leading-relaxed my-2\"><b>Kim giờ:</b> chu kì $T_h = 12\\text{ h} = 43200\\text{ s}$, bán kính $R_h = 90\\text{ cm} = 0{,}9\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">$v_h = \\dfrac{2\\pi}{43200}\\cdot 0{,}9 \\approx 1{,}31\\cdot 10^{-4}\\text{ m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy tốc độ dài của hai đầu mút kim phút và kim giờ lần lượt là $2{,}09\\cdot 10^{-3}\\text{ m/s}$ và $1{,}31\\cdot 10^{-4}\\text{ m/s}$, chọn đáp án B.</p>","options":["$\\text{1,57.1}\\text{0}^{\\text{-3}}\\text{ m/s,} \\text{1,74.1}\\text{0}^{\\text{-4}}\\text{ m/s.}$","$\\text{2,09.1}\\text{0}^{\\text{-3}}\\text{ m/s, 1,31.1}\\text{0}^{\\text{-4}}\\text{ m/s.}$","$\\text{3,66.1}\\text{0}^{\\text{-3}}\\text{ m/s,} \\text{1,31.1}\\text{0}^{\\text{-4}}\\text{ m/s.}$","$\\text{2,09.1}\\text{0}^{\\text{-3}}\\text{ m/s,} \\text{1,90.1}\\text{0}^{\\text{-4}}\\text{ m/s.}$"],"answer":1}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"de","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đĩa tròn bán kính $\\text{10 cm,}$ quay đều mỗi vòng hết $\\text{0,2 s.}$ Tốc độ dài của một điểm nằm trên vành đĩa có giá trị là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 10\\text{ cm} = 0{,}1\\text{ m}$, chu kỳ $T = 0{,}2\\text{ s}$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc của chuyển động tròn đều: $\\omega = \\dfrac{2\\pi}{T}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\omega = \\dfrac{2\\pi}{0{,}2} = 10\\pi\\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ dài của điểm trên vành đĩa: $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = 10\\pi \\cdot 0{,}1 = \\pi \\approx 3{,}14\\text{ m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ dài của điểm trên vành đĩa là $3{,}14\\text{ m/s}$, chọn D.</p>","options":["$\\text{314 m/s.}$","$\\text{31,4 m/s.}$","$\\text{0,314 m/s.}$","$\\text{3,14 m/s.}$"],"answer":3}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh nhân tạo của Trái Đất ở độ cao $\\text{300 km}$ bay với tốc độ $\\text{7,9 km/s.}$ Coi chuyển động là tròn đều. Bán kính trái đất bằng $\\text{6400 km.}$ Tốc độ góc và chu kì của vệ tinh có giá trị bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Vệ tinh chuyển động tròn đều quanh Trái Đất. Bán kính quỹ đạo bằng bán kính Trái Đất cộng độ cao:</p><p class=\"text-base leading-relaxed my-2\">$r = R + h = 6400 + 300 = 6700\\ \\text{km} = 6{,}7.10^{6}\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc được tính từ công thức liên hệ giữa tốc độ dài và tốc độ góc: $v = \\omega r$, suy ra $\\omega = \\dfrac{v}{r}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 7{,}9\\ \\text{km/s} = 7900\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$\\omega = \\dfrac{7900}{6{,}7.10^{6}} \\approx 1{,}2.10^{-3}\\ \\text{rad/s}$</p><p class=\"text-base leading-relaxed my-2\">Chu kì quay được tính từ công thức $T = \\dfrac{2\\pi}{\\omega}$ (hoặc $T = \\dfrac{2\\pi r}{v}$):</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{2\\pi r}{v} = \\dfrac{2\\pi \\cdot 6{,}7.10^{6}}{7900} \\approx 5{,}32.10^{3}\\ \\text{s}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $\\omega \\approx 1{,}2.10^{-3}\\ \\text{rad/s}$ và $T \\approx 5{,}32.10^{3}\\ \\text{s}$, đáp án B.</p>","options":["$\\text{ω}\\approx\\text{12.1}\\text{0}^{-\\text{3}}\\text{ rad/s, T}\\approx\\text{5,23.1}\\text{0}^{\\text{3}}\\text{s.}$","$\\text{ω}\\approx\\text{1,2.1}\\text{0}^{-\\text{3}}\\text{ rad/s, T}\\approx\\text{5,32.1}\\text{0}^{\\text{3}}\\text{s.}$","$\\text{ω}\\approx\\text{1,2.1}\\text{0}^{-\\text{3}}\\text{ rad/s,T}\\approx\\text{5,23.1}\\text{0}^{\\text{4}}\\text{s.}$","$\\text{ω}\\approx\\text{1,2.1}\\text{0}^{-\\text{3}}\\text{ rad/s,T}\\approx\\text{5,23.1}\\text{0}^{\\text{3}}\\text{s.}$"],"answer":1}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một quạt máy quay với vận tốc $\\text{400 vòng/phút.}$ Cánh quạt dài $\\text{0,82 m.}$ Vận tốc dài và vận tốc góc của một điểm ở đầu cánh có giá trị là</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đổi tần số: $f = 400 \\text{ vòng/phút} = \\dfrac{400}{60} \\text{ vòng/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc góc: $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = 2 \\cdot 3{,}14 \\cdot \\dfrac{400}{60} \\approx 41{,}87 \\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vận tốc dài của điểm ở đầu cánh (bán kính $R = 0{,}82$ m): $v = \\omega R$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = 41{,}87 \\cdot 0{,}82 \\approx 34{,}33 \\text{ m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $\\omega \\approx 41{,}87$ rad/s và $v \\approx 34{,}33$ m/s, đáp án D.</p>","options":["$\\text{ω}=\\text{48,17 rad/s, v}=\\text{34,33 m/s.}$","$\\text{ω}=\\text{41,78 rad/s, v}=\\text{34,33 m/s.}$","$\\text{ω}=\\text{14,87 rad/s, v}=\\text{34,33 m/s.}$","$\\text{ω}=\\text{41,87 rad/s, v}=\\text{34,33 m/s.}$"],"answer":3}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Quan sát đồng hồ kim, hiện tại là $\\text{5}$ giờ <strong>đúng</strong>. Sau khoảng thời gian ngắn nhất $\\text{Δt}$ thì hai kim trùng nhau. Giá trị của $\\text{Δt}$ bằng</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương là chiều quay của kim, tính góc quay từ vị trí 12 giờ.</p><p class=\"text-base leading-relaxed my-2\">Lúc 5 giờ đúng: kim giờ ở vị trí $\\alpha_{0,h}=5\\cdot 30^\\circ=150^\\circ$, kim phút ở vị trí $\\alpha_{0,m}=0^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc: kim phút $\\omega_m=360^\\circ/\\text{h}$, kim giờ $\\omega_h=30^\\circ/\\text{h}$.</p><p class=\"text-base leading-relaxed my-2\">Hai kim trùng nhau khi góc quay của kim phút đuổi kịp kim giờ: $\\alpha_m=\\alpha_h+360^\\circ k$, với $k=0,1,2,\\dots$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow\\ 0+360\\,\\Delta t=150+30\\,\\Delta t+360k$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow\\ 330\\,\\Delta t=150+360k$</p><p class=\"text-base leading-relaxed my-2\">Thời gian ngắn nhất ứng với $k=0$: $\\Delta t=\\dfrac{150}{330}=\\dfrac{5}{11}$ giờ.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $\\Delta t=\\dfrac{5}{11}$ giờ (khoảng 27,3 phút), đáp án B.</p>","options":["$\\frac{\\text{7}}{\\text{9}}$ giờ.","$\\frac{\\text{5}}{\\text{11}}$ giờ.","$\\frac{\\text{7}}{\\text{11}}$ giờ.","$\\frac{\\text{5}}{\\text{9}}$ giờ."],"answer":1}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"multiple_choice","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một chiếc đồng hồ đang hoạt động bình thường, hiện tại kim giờ và kim phút không trùng nhau. Sau <strong>đúng</strong> $\\text{24}$ giờ (tức $\\text{1}$ ngày đêm) hai kim đó trùng nhau</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Chọn chiều dương cùng chiều quay của kim, gốc tại vị trí 12 giờ. Góc quay trong 1 giờ: kim phút quay được $360^\\circ$, kim giờ quay được $30^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc tương đối của kim phút so với kim giờ: $\\Delta\\varphi = (360^\\circ - 30^\\circ)\\cdot t = 330^\\circ \\cdot t$ (với $t$ tính bằng giờ).</p><p class=\"text-base leading-relaxed my-2\">Hai kim trùng nhau khi góc tương đối bằng bội số nguyên của $360^\\circ$: $330^\\circ \\cdot t = k\\cdot 360^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Trong $t = 24$ h, góc tương đối tăng thêm: $\\Delta\\varphi = 330^\\circ \\cdot 24 = 7920^\\circ = 22 \\cdot 360^\\circ$.</p><p class=\"text-base leading-relaxed my-2\">Vì thời điểm ban đầu hai kim không trùng nhau nên góc tương đối ban đầu không phải bội số của $360^\\circ$. Khi góc tương đối tăng thêm $22 \\cdot 360^\\circ$, nó đi qua đúng $22$ bội số của $360^\\circ$, tức hai kim trùng nhau $22$ lần (không tính thời điểm ban đầu).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: trong 24 giờ hai kim trùng nhau $22$ lần. Đáp án D.</p>","options":["$\\text{18}$ lần.","$\\text{19}$ lần.","$\\text{21}$ lần.","$\\text{22}$ lần."],"answer":3}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Cho các phát biểu sau về chuyển động tròn đều. Xét tính <strong>đúng</strong>, <strong>sai</strong> của các phát biểu sau:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Kiến thức:</b> Trong chuyển động tròn đều, chu kì $T$ là thời gian vật đi hết một vòng. Tốc độ góc $\\omega=\\dfrac{2\\pi}{T}$, tốc độ dài $v=\\omega r$, gia tốc hướng tâm $a_{ht}=\\omega^2 r=\\dfrac{v^2}{r}$.</p><p class=\"text-base leading-relaxed my-2\"><b>a) Đúng.</b> Đây là định nghĩa của chu kì: thời gian để vật đi được một vòng tròn.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Đúng.</b> Công thức $\\omega=\\dfrac{2\\pi}{T}$ đúng. Vì $T$ không đổi nên $\\omega$ không đổi, và $\\omega$ không phụ thuộc bán kính $r$.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Sai.</b> Công thức $a_{ht}=\\omega^2 r=\\left(\\dfrac{2\\pi}{T}\\right)^2 r$ đúng. Với $T$ không đổi thì $\\omega$ không đổi, nên $a_{ht}$ tỉ lệ thuận với $r$: bán kính càng lớn thì gia tốc càng lớn, không phải càng nhỏ.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Công thức $v=\\omega r=\\dfrac{2\\pi}{T}r$ đúng. Với $T$ không đổi, $v$ tỉ lệ thuận với $r$: bán kính càng lớn thì tốc độ dài càng lớn.</p>","statements":[{"text":"Chu kỳ T của chuyển động tròn đều là thời gian để vật đi được một vòng.","answer":true},{"text":"Tốc độ góc của chuyển động tròn đều là $\\text{ω}=\\frac{\\text{2π}}{\\text{T}}\\text{,}$ vì chu kì không đổi nên tốc độ góc cũng không thay đổi không phụ thuộc vào bán kính quỹ đạo.","answer":true},{"text":"Gia tốc của chuyển động tròn đều là gia tốc hướng tâm là $\\text{a}_{\\text{ht}}=\\text{ω}^{\\text{2}}\\text{r}=\\left( \\frac{\\text{2π}}{\\text{T}} \\right)^{\\text{2}}\\text{r,}$ chu kì không đổi nên bán kính càng lớn thì gia tốc càng nhỏ.","answer":false},{"text":"Tốc độ dài của chuyển động tròn đều là $\\text{v}=\\text{ωr}=\\frac{\\text{2π}}{\\text{T}}\\text{r,}$ chu kì không đổi nên bán kính càng lớn thì tốc độ dài càng lớn.","answer":true}]}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một đồng hồ công cộng gắn trên tháp chuông ở trung tâm thành phố có kim phút dài $\\text{1,2 m}$ và kim giờ dài $\\text{90 cm.}$ Xét tính <strong>đúng</strong>, <strong>sai</strong> của các phát biểu sau:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Tốc độ dài của một điểm chuyển động tròn đều: $v = \\dfrac{2\\pi R}{T}$, với $R$ là bán kính quỹ đạo và $T$ là chu kì quay.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Kim phút quay một vòng trong 1 giờ: $T_{\\text{phút}} = 1\\text{ h} = 3600\\text{ s}$. Phát biểu <b>đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Với $R_{\\text{phút}} = 1{,}2\\text{ m}$ và $T_{\\text{phút}} = 3600\\text{ s}$:</p><p class=\"text-base leading-relaxed my-2\">$v_{\\text{phút}} = \\dfrac{2\\pi \\cdot 1{,}2}{3600} \\approx 2{,}09\\cdot 10^{-3}\\text{ m/s}$</p><p class=\"text-base leading-relaxed my-2\">Giá trị $20{,}9\\cdot 10^{-3}\\text{ m/s}$ trong đề gấp 10 lần kết quả đúng. Phát biểu <b>sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Kim giờ quay một vòng trong 12 giờ: $T_{\\text{giờ}} = 12 \\cdot 3600 = 43200\\text{ s}$. Với $R_{\\text{giờ}} = 0{,}9\\text{ m}$:</p><p class=\"text-base leading-relaxed my-2\">$v_{\\text{giờ}} = \\dfrac{2\\pi \\cdot 0{,}9}{43200} \\approx 1{,}31\\cdot 10^{-4}\\text{ m/s}$</p><p class=\"text-base leading-relaxed my-2\">Phát biểu <b>đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Tỉ số tốc độ dài:</p><p class=\"text-base leading-relaxed my-2\">$\\dfrac{v_{\\text{phút}}}{v_{\\text{giờ}}} = \\dfrac{R_{\\text{phút}}}{R_{\\text{giờ}}} \\cdot \\dfrac{T_{\\text{giờ}}}{T_{\\text{phút}}} = \\dfrac{1{,}2}{0{,}9} \\cdot \\dfrac{43200}{3600} = \\dfrac{4}{3} \\cdot 12 = 16$</p><p class=\"text-base leading-relaxed my-2\">Đề ghi $\\dfrac{131}{2090} \\approx 0{,}063$, không khớp. Phát biểu <b>sai</b>.</p>","statements":[{"text":"Chu kì quay của kim phút là 3600 s.","answer":true},{"text":"Tốc độ dài của đầu mút kim phút 20,9.10 − 3 m/s.","answer":false},{"text":"Tốc độ dài của đầu mút kim giờ là 1,31.10 − 4 m/s.","answer":true},{"text":"Tỉ số giữa tốc độ dài của đầu mút kim phút và tốc độ dài của đầu mút kim giờ là $\\frac{\\text{131}}{\\text{2090}}\\text{.}$","answer":false}]}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một vật chuyển động tròn đều trên đường tròn bán kính 50 cm. Sau thời gian 2 giây vật đi được cung tròn dài 6 cm. Xét tính <strong>đúng</strong>, <strong>sai</strong> của các phát biểu sau:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Dữ kiện:</strong> bán kính $r = 50\\ \\text{cm} = 0{,}5\\ \\text{m}$; quãng đường cung tròn $s = 6\\ \\text{cm} = 0{,}06\\ \\text{m}$; thời gian $t = 2\\ \\text{s}$.</p><p class=\"text-base leading-relaxed my-2\"><strong>Góc quét (ý a):</strong> công thức $\\alpha = \\dfrac{s}{r}$ (góc tính bằng radian).</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\alpha = \\dfrac{0{,}06}{0{,}5} = 0{,}12\\ \\text{rad}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang độ: $\\alpha = 0{,}12 \\cdot \\dfrac{180^\\circ}{\\pi} \\approx 6{,}875^\\circ$, không phải $0{,}12^\\circ$. Vậy <strong>a) Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Tốc độ góc (ý b):</strong> công thức $\\omega = \\dfrac{\\alpha}{t}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $\\omega = \\dfrac{0{,}12}{2} = 0{,}06\\ \\text{rad/s}$. Vậy <strong>b) Đúng</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Tốc độ dài (ý c):</strong> công thức $v = \\dfrac{s}{t}$ hoặc $v = r\\omega$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = \\dfrac{0{,}06}{2} = 0{,}03\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Không phải $0{,}3\\ \\text{m/s}$. Vậy <strong>c) Sai</strong>.</p><p class=\"text-base leading-relaxed my-2\"><strong>Chu kỳ (ý d):</strong> công thức $T = \\dfrac{2\\pi}{\\omega}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $\\pi \\approx 3{,}14$: $T = \\dfrac{2 \\cdot 3{,}14}{0{,}06} \\approx 104{,}67\\ \\text{s}$. Vậy <strong>d) Đúng</strong>.</p>","statements":[{"text":"Góc ở tâm mà bán kính quét được sau 2 giây là 0,12 độ.","answer":false},{"text":"Tốc độ góc của vật là 0,06 rad/s.","answer":true},{"text":"Tốc độ chuyển động của vật xấp xĩ bằng 0,3 m/s.","answer":false},{"text":"Chu kỳ chuyển động của vật bằng 104,67 s.","answer":true}]}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"true_false","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Vòng quay Sun Wheel tại Asia Park của TP Đà Nẵng có đường kính $\\text{105 m,}$ lọt top 5 các vòng quay cao nhất hành tinh, cũng là 1 trong 2 vòng quay cao nhất Việt Nam. Vòng quay có tổng cộng $\\text{64}$ cabin, mỗi cabin có sức chứa tối đa 6 người. Mỗi lượt quay một vòng, vòng quay Sun Wheel đưa du khách chiêm ngưỡng toàn cảnh Đà Nẵng trong thời gian $\\text{15}$ phút. Xét tính <strong>đúng</strong>, <strong>sai</strong> của các phát biểu sau:</p>","explanation":"<p class=\"text-base leading-relaxed my-2\"><b>Ý a)</b> Một vòng quay ứng với góc quay $\\theta = 2\\pi$ rad (theo định nghĩa radian, một vòng tròn đầy đủ là $2\\pi$ rad). Phát biểu <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý b)</b> Quỹ đạo của điểm treo cabin là đường tròn có đường kính $d = 105$ m, nên bán kính $R = 52{,}5$ m.</p><p class=\"text-base leading-relaxed my-2\">Chu vi quỹ đạo: $C = 2\\pi R = \\pi d = \\pi \\cdot 105 \\approx 329{,}87$ m.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $32{,}97$ m không đúng (sai khoảng 10 lần). Phát biểu <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý c)</b> Thời gian một vòng quay: $T = 15$ phút $= 900$ s.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ góc: $\\omega = \\dfrac{2\\pi}{T} = \\dfrac{2\\pi}{900} = \\dfrac{\\pi}{450}$ rad/s. Phát biểu <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>Ý d)</b> Tần số: $f = \\dfrac{1}{T} = \\dfrac{1}{900}$ Hz $\\approx 1{,}11 \\cdot 10^{-3}$ Hz.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $900$ Hz là sai; thực ra $900$ s là chu kì $T$, không phải tần số. Phát biểu <b>Sai</b>.</p>","statements":[{"text":"Một vòng quay tương ứng với góc θ = 2π rad.","answer":true},{"text":"Chiều dài quĩ đạo của mỗi điểm treo cabin khi vòng quay chuyển động được một vòng là 32,97 m.","answer":false},{"text":"Tốc độ góc chuyển động của vòng quay Sun Wheel là $\\frac{\\text{π}}{\\text{450}} \\text{rad/s.}$","answer":true},{"text":"Tần số chuyển động của vòng quay Sun Wheel là 900 Hz.","answer":false}]}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Kim giờ của một đồng hồ dài bằng $\\frac{\\text{3}}{\\text{4}}$ kim phút. Tỉ số giữa tốc độ dài của đầu mút kim phút và kim dài là bao nhiêu?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Gọi $r_m$ là chiều dài kim phút và $r_h$ là chiều dài kim giờ. Theo đề, $r_h = \\frac{3}{4}r_m$.</p><p class=\"text-base leading-relaxed my-2\">Tốc độ dài của đầu mút một kim quay đều: $v = \\omega r$, với $\\omega = \\frac{2\\pi}{T}$ là tốc độ góc và $T$ là chu kỳ quay.</p><p class=\"text-base leading-relaxed my-2\">Chu kỳ kim phút: $T_p = 1$ giờ; chu kỳ kim giờ: $T_g = 12$ giờ. Suy ra $\\frac{\\omega_p}{\\omega_g} = \\frac{T_g}{T_p} = 12$.</p><p class=\"text-base leading-relaxed my-2\">Tỉ số tốc độ dài: $\\frac{v_p}{v_g} = \\frac{\\omega_p r_m}{\\omega_g r_h} = 12 \\cdot \\frac{r_m}{r_h}$.</p><p class=\"text-base leading-relaxed my-2\">Thay $r_h = \\frac{3}{4}r_m$: $\\frac{r_m}{r_h} = \\frac{4}{3}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\frac{v_p}{v_g} = 12 \\cdot \\frac{4}{3} = 16$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tỉ số giữa tốc độ dài của đầu mút kim phút và kim giờ là $16$.</p>","answer":"16"}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Liên hệ tốc độ dài và tốc độ góc","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Hai điểm A và B nằm trên cùng một bán kính của một vô lăng đang quay đều, cách nhau $\\text{20 cm.}$ Điểm A ở phía ngoài có vận tốc $\\text{0,6 m/s,}$ còn điểm B có vận tốc $\\text{0,2 m/s.}$ Vận tốc góc của vô lăng là bao nhiêu rad/s?</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai điểm A, B cùng nằm trên một bán kính nên cùng vận tốc góc $\\omega$. Với chuyển động tròn đều, vận tốc dài $v = \\omega r$.</p><p class=\"text-base leading-relaxed my-2\">Gọi $r_A$, $r_B$ là bán kính quỹ đạo của A và B. Vì A ở phía ngoài nên $r_A - r_B = AB = 0{,}20$ m.</p><p class=\"text-base leading-relaxed my-2\">Ta có $v_A - v_B = \\omega (r_A - r_B)$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = \\dfrac{v_A - v_B}{AB} = \\dfrac{0{,}6 - 0{,}2}{0{,}20} = 2$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: vận tốc góc của vô lăng là $\\omega = 2$ rad/s.</p>","answer":"2"}$q$::jsonb, 147, $q$Liên hệ tốc độ dài và tốc độ góc$q$),
($q${"type":"short_answer","form":"bai_tap","topic":"Tốc độ góc, chu kì, tần số","difficulty":"trung-binh","difficultySource":"ai","question":"<p class=\"text-base leading-relaxed my-2\">Một xe tải đang chuyển động thẳng đều có tốc độ $\\text{v}=\\text{72 km/h}$ có bánh xe có đường kính $\\text{80 cm.}$ Chu kì của đầu van xe có giá trị là bao nhiêu giây? (kết quả làm tròn đến hai chữ số thập phân sau dấu phẩy).</p>","explanation":"<p class=\"text-base leading-relaxed my-2\">Đầu van chuyển động tròn đều quanh trục bánh xe; xe chuyển động thẳng đều không trượt nên tốc độ dài của đầu van (so với trục bánh xe) bằng tốc độ xe: $v = 72\\ \\text{km/h} = 20\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Bán kính bánh xe: $r = \\dfrac{d}{2} = \\dfrac{0{,}8}{2} = 0{,}4\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\omega = \\dfrac{v}{r} = \\dfrac{20}{0{,}4}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\omega = 50\\ \\text{rad/s}$</p><p class=\"text-base leading-relaxed my-2\">$T = \\dfrac{2\\pi}{\\omega} = \\dfrac{2\\pi}{50}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow T \\approx 0{,}1257\\ \\text{s} \\approx 0{,}13\\ \\text{s}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $T \\approx 0{,}13\\ \\text{s}$.</p>","answer":"0,13"}$q$::jsonb, 146, $q$Tốc độ góc, chu kì, tần số$q$)) as v(q, tid, tname)
